shader.code:
// Chromatophore: the skin of a cuttlefish, seen up close. Three layers of
// pigment sacs sit on a shimmering iridescent ground. Each sac opens into a
// wide disc of colour or shuts to a dark dot; waves of opening and closing
// travel across the skin, as clouds or as spirals, and every beat pushes
// them a step further. Crowded sacs press flat against each other.

#define TAU 6.28318531

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

vec2 hash2(vec2 p) {
  float h = hash(p);
  return vec2(h, hash(p + h * 37.0 + 11.7));
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 3; i++) {
    v += a * noise(p);
    p = mat2(0.8, 0.6, -0.6, 0.8) * p * 2.03;
    a *= 0.5;
  }
  return v / 0.875;
}

// How far open (0..1) a sac at skin position c is.
float activation(vec2 c, float j, float seed) {
  // Warped sines: cheap, and smooth enough to read as drifting clouds.
  float cloud = sin(c.x * 1.3 + 1.8 * sin(c.y * 0.9 + j * 0.05) + seed * 7.0) +
    sin(c.y * 1.6 + 1.8 * sin(c.x * 0.7 - j * 0.04) - seed * 3.0);
  cloud *= 0.45;
  vec2 f = c - 0.7 * vec2(sin(j * 0.05), cos(j * 0.041));
  float spiral = length(f) * 1.1 - atan(f.y, f.x) / TAU * 2.0;
  float ph = mix(cloud, spiral, pattern) - j * 0.11 + seed * 0.31;
  float w = 0.5 + 0.5 * sin(TAU * ph);
  return smoothstep(0.0, 1.0, (w - (1.0 - tension)) * 2.5 + 0.5);
}

// Paints one layer of sacs over col.
vec3 sacs(vec3 col, vec2 p, mat2 m, float sc, float seed, float j, float hue, float px) {
  // Every layer's grid is turned differently so no rows line up.
  vec2 g = m * p * sc;
  vec2 id = floor(g);
  vec2 f = fract(g);
  float pxs = px * sc;

  // Nearest and second nearest sac, measured in sac radii, so neighbours
  // meet along a flat seam instead of overlapping.
  float q1 = 1e3;
  float q2 = 1e3;
  vec2 d1 = vec2(0.0);
  float r1 = 1.0;
  float a1 = 0.0;
  float h1 = 0.0;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 o = vec2(float(x), float(y));
      vec2 cid = id + o;
      vec2 rnd = hash2(cid + seed * 17.3);
      vec2 d = f - (o + 0.5 + (rnd - 0.5) * 0.9);
      float act = activation(((cid + 0.5) / sc) * m, j, seed);
      float r = mix(0.1, 0.6, act) * (0.8 + 0.4 * rnd.x);
      // The rim of an open sac is slightly lobed.
      float len = length(d);
      vec2 u = d / max(len, 1e-4);
      r *= 1.0 + 0.07 * act * (rnd.y - 0.5) * 2.0 * u.x * (4.0 * u.x * u.x - 3.0);
      float q = len / r;
      if (q < q1) {
        q2 = q1;
        q1 = q;
        d1 = d;
        r1 = r;
        a1 = act;
        h1 = rnd.y;
      } else if (q < q2) {
        q2 = q;
      }
    }
  }

  float aa = pxs / r1;
  float cover = smoothstep(1.0 + aa, 1.0 - aa - 0.04, q1);
  // Pigment is dense and dark when the sac is shut, vivid when it opens.
  vec3 pig = palette(hue + h1 * 0.14 + a1 * 0.08);
  vec3 sac = pig * mix(0.42, 1.05, a1) * (1.0 - 0.5 * q1 * q1);
  sac = mix(sac, sac * sac * 1.3, 0.35);
  // A wet highlight on the dome.
  vec2 hp = d1 / r1 - vec2(-0.32, 0.36);
  sac += (0.2 + 0.5 * a1) * smoothstep(0.34, 0.0, length(hp));
  // Dark seam where two sacs press together.
  sac *= 0.35 + 0.65 * smoothstep(0.0, 0.1 + aa, q2 - q1);

  // The sac shades the skin around it.
  col *= 1.0 - 0.45 * smoothstep(1.5, 1.0, q1);
  return mix(col, sac, cover * mix(1.0, 0.86, a1));
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;
  float px = 2.0 / resolution.y;

  // The skin itself moves: slow turn, breathing, a gentle undulation.
  p = rot(j * 0.011) * p * (1.0 + 0.08 * sin(j * 0.07));
  p += 0.05 * vec2(noise(p * 1.7 + j * 0.05), noise(p * 1.7 + 31.0 - j * 0.04));

  float hue = colour + j * 0.009;
  float sc = mix(2.0, 9.0, scale * scale);

  // Iridescent ground: shifting metallic bands with glittering platelets.
  float n1 = fbm(p * 1.3 + vec2(j * 0.03, 0.0));
  float n2 = fbm(p * 3.1 + n1 * 2.5 - vec2(0.0, j * 0.04));
  vec3 ground = palette(hue + 0.55 + n1 * 0.5 + n2 * 0.35);
  ground *= 0.2 + 0.8 * smoothstep(0.25, 0.8, n2);
  vec2 pg = p * sc * 5.0;
  float ph = hash(floor(pg));
  float glint = pow(0.5 + 0.5 * sin(j * 0.9 + ph * TAU), 10.0);
  ground += glint * ph * smoothstep(0.5, 0.1, length(fract(pg) - 0.5));
  vec3 col = ground * mix(0.04, 1.0, sheen);

  col = sacs(col, p, rot(0.4), sc, 1.0, j, hue, px);
  col = sacs(col, p, rot(1.5), sc * 1.7, 2.0, j, hue + 0.36, px);
  col = sacs(col, p, rot(2.7), sc * 2.9, 3.0, j, hue + 0.68, px);

  col *= 1.0 - 0.35 * smoothstep(0.7, 1.9, length(uv - 0.5) * 2.0);
  return clamp(col, 0.0, 1.0);
}
